-- Migration: 20261128_create_agent_activity_tables.sql
-- Description: Creates persistent storage tables for the Natural-Language Agent Activity & Reasoning Transparency System.
-- Tables:
--   1. public.agent_executions: Tracks query executions, tenant scope, lifecycle, and overall status.
--   2. public.agent_execution_events: Structured, monotonic execution events capturing ground truth tool and planning actions.
--   3. public.agent_narration_events: Human-readable narrative updates generated by the LLM Narrator Engine or fallback.

-- ============================================================================
-- 1. Table: public.agent_executions
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.agent_executions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL,
    user_id UUID,
    conversation_id UUID,
    agent_type TEXT NOT NULL DEFAULT 'coach',
    query TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    metadata JSONB DEFAULT '{}'::jsonb,
    started_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Indexes for agent_executions
CREATE INDEX IF NOT EXISTS idx_agent_executions_company_user ON public.agent_executions (company_id, user_id);
CREATE INDEX IF NOT EXISTS idx_agent_executions_conversation ON public.agent_executions (conversation_id);
CREATE INDEX IF NOT EXISTS idx_agent_executions_started_at ON public.agent_executions (started_at DESC);

-- Enable RLS
ALTER TABLE public.agent_executions ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'agent_executions' AND policyname = 'agent_executions_tenant_isolation'
    ) THEN
        CREATE POLICY agent_executions_tenant_isolation ON public.agent_executions
            FOR ALL
            USING (
                company_id IN (
                    SELECT company_id FROM public.users WHERE user_id = auth.uid()
                )
                OR auth.role() = 'service_role'
            );
    END IF;
END $$;


-- ============================================================================
-- 2. Table: public.agent_execution_events
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.agent_execution_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    execution_id UUID NOT NULL REFERENCES public.agent_executions(id) ON DELETE CASCADE,
    parent_event_id UUID,
    sequence INT NOT NULL,
    schema_version TEXT NOT NULL DEFAULT '1.0',
    stage TEXT NOT NULL CHECK (stage IN (
        'understanding', 'planning', 'information_gathering', 'tool_execution',
        'observation', 'validation', 'recovery', 'synthesis', 'completion'
    )),
    event_type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'completed' CHECK (status IN ('started', 'in_progress', 'completed', 'failed', 'retrying')),
    visibility TEXT NOT NULL DEFAULT 'user' CHECK (visibility IN ('user', 'internal', 'audit')),
    source_component TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    duration_ms INT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT uq_execution_event_sequence UNIQUE (execution_id, sequence)
);

-- Indexes for agent_execution_events
CREATE INDEX IF NOT EXISTS idx_execution_events_exec_seq ON public.agent_execution_events (execution_id, sequence ASC);
CREATE INDEX IF NOT EXISTS idx_execution_events_created_at ON public.agent_execution_events (created_at DESC);

-- Enable RLS
ALTER TABLE public.agent_execution_events ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'agent_execution_events' AND policyname = 'agent_execution_events_tenant_isolation'
    ) THEN
        CREATE POLICY agent_execution_events_tenant_isolation ON public.agent_execution_events
            FOR ALL
            USING (
                execution_id IN (
                    SELECT id FROM public.agent_executions WHERE company_id IN (
                        SELECT company_id FROM public.users WHERE user_id = auth.uid()
                    )
                )
                OR auth.role() = 'service_role'
            );
    END IF;
END $$;


-- ============================================================================
-- 3. Table: public.agent_narration_events
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.agent_narration_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    execution_id UUID NOT NULL REFERENCES public.agent_executions(id) ON DELETE CASCADE,
    source_event_id UUID,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    stage TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'completed',
    provider TEXT NOT NULL DEFAULT 'heuristic_fallback',
    model TEXT,
    is_fallback BOOLEAN NOT NULL DEFAULT false,
    duration_ms INT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- Indexes for agent_narration_events
CREATE INDEX IF NOT EXISTS idx_narration_events_execution ON public.agent_narration_events (execution_id);
CREATE INDEX IF NOT EXISTS idx_narration_events_created_at ON public.agent_narration_events (created_at DESC);

-- Enable RLS
ALTER TABLE public.agent_narration_events ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'agent_narration_events' AND policyname = 'agent_narration_events_tenant_isolation'
    ) THEN
        CREATE POLICY agent_narration_events_tenant_isolation ON public.agent_narration_events
            FOR ALL
            USING (
                execution_id IN (
                    SELECT id FROM public.agent_executions WHERE company_id IN (
                        SELECT company_id FROM public.users WHERE user_id = auth.uid()
                    )
                )
                OR auth.role() = 'service_role'
            );
    END IF;
END $$;
